export function subscribe(email) {
  if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email)) return { ok: false, error: '邮箱格式不对' };
  return { ok: true, list: 'weekly', email: email.toLowerCase() };
}

