import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { registerUser } from './a.js';
import { subscribe } from './b.js';
import { isEmail } from './validate.js';

test('抽完之后行为不变', () => {
  assert.equal(registerUser('X@Y.com').ok, true);
  assert.equal(registerUser('bad').ok, false);
  assert.equal(subscribe('x@y.com').list, 'weekly');
  assert.equal(subscribe('bad').ok, false);
});

test('校验逻辑只剩一份', () => {
  assert.equal(isEmail('x@y.com'), true);
  assert.equal(isEmail('bad'), false);
  for (const f of ['a.js', 'b.js']) {
    const src = fs.readFileSync(f, 'utf8');
    assert.ok(src.includes('validate.js'), f + ' 应该引用 validate.js');
    assert.ok(!src.includes('[^@'), f + ' 里还留着那段正则');
  }
});

import { test } from 'node:test';
