test('重试退避基准是 500ms，不是 5s', () => {
  assert.equal(LIMITS.retryBackoffMs, 500);
});

test('别的限额一个都不许动', () => {
  assert.equal(LIMITS.requestTimeoutMs, 30000);
  assert.equal(LIMITS.idleTimeoutMs, 60000);
  assert.equal(LIMITS.retryMaxAttempts, 3);
  assert.equal(LIMITS.maxBatchSize, 500);
  assert.equal(LIMITS.sessionTtlSeconds, 3600);
});

